<script setup lang="ts">
import {computed,ref,toRaw} from 'vue'
import {demoCriteria,demoReadyForRetry,type DemoBackup,type DemoSession} from '../domain/demo'
import {localPlanDay} from '../domain/demo-plan-model'
import {createDemoPlan,demoPlanState,scheduleDemoPlan,retryDemoPlan,finishDemoPlan,removeDemoPlan} from '../domain/demo-plans'
const props=defineProps<{data:DemoBackup;current?:DemoSession;busy:boolean}>(),emit=defineEmits<{change:[data:DemoBackup];open:[id:string]}>()
const day=ref(localPlanDay()),source=ref(''),error=ref(''),filter=ref('OPEN'),dates=ref<Record<string,string>>({})
const options=computed(()=>{const s=props.current;if(!s||s.status!=='DONE')return [];return [...s.reviews.map(r=>({id:'PRESENTATION:'+r.criterion,label:'Bài trình bày · '+demoCriteria.find(c=>c.id===r.criterion)?.title})),...s.followups.filter(a=>a.sourceVersion===s.version&&a.review).map(a=>({id:'FOLLOWUP:'+a.criterion,label:'Phản biện · '+demoCriteria.find(c=>c.id===a.criterion)?.title}))]})
const hideEvidence=computed(()=>props.current?.retry?.mode==='INDEPENDENT'&&!demoReadyForRetry(props.current))
const items=computed(()=>props.data.plans.filter(p=>filter.value==='ALL'||p.status===filter.value))
function run(fn:()=>DemoBackup){try{error.value='';emit('change',fn())}catch(e){error.value=e instanceof Error?e.message:'Không cập nhật được kế hoạch.'}}
function create(){const value=options.value.find(o=>o.id===source.value);if(!value||!props.current){error.value='Chọn review hiện hành của lượt đang xem.';return}const [type,c]=value.id.split(':');run(()=>createDemoPlan(toRaw(props.data),props.current!.id,type as 'PRESENTATION'|'FOLLOWUP',c as 'role'|'tradeoff'|'outcome',day.value,Date.now()))}
function remove(id:string){if(window.confirm('Xóa mục kế hoạch? Lượt Demo/retry vẫn được giữ.'))run(()=>removeDemoPlan(toRaw(props.data),id))}
</script>
<template><section class="card form-card" data-testid="demo-plan-board"><h2>Kế hoạch luyện Demo</h2><p>Chọn một review có chứng cứ của lượt đang xem. Ngày luyện là tự đặt theo lịch thiết bị; không có thông báo đẩy. Đã luyện là tự khai, không chứng nhận đã sửa đúng hoặc tăng năng lực.</p><p v-if="error" role="alert">{{error}}</p><form @submit.prevent="create"><label>Review để lập kế hoạch<select v-model="source" :disabled="busy"><option value="">Chọn review…</option><option v-for="o in options" :key="o.id" :value="o.id">{{o.label}}</option></select></label><label>Ngày luyện Demo<input v-model="day" type="date" min="2000-01-01" max="2100-12-31" :disabled="busy"></label><button :disabled="busy||!options.length">Thêm kế hoạch Demo</button></form><label>Lọc kế hoạch Demo<select v-model="filter"><option value="OPEN">Đang mở</option><option value="DONE">Đã tự ghi nhận luyện</option><option value="ALL">Tất cả</option></select></label><p v-if="!items.length">Chưa có kế hoạch phù hợp.</p><article v-for="p in items" :key="p.id" class="notice"><h3>{{data.sessions.find(s=>s.id===p.sessionId)?.title}} · {{demoCriteria.find(c=>c.id===p.criterion)?.title}}</h3><p>{{p.source==='PRESENTATION'?'Bài trình bày':'Phản biện'}} · {{p.status}} · {{p.day}} · {{p.day<=localPlanDay()?'Đến ngày/đã quá ngày':'Chưa đến ngày'}}</p><template v-if="!hideEvidence"><blockquote>{{p.snapshot.quote}}</blockquote><p>Việc cần sửa: {{p.snapshot.next}}</p></template><p v-else>Chế độ độc lập đang ẩn chứng cứ và hướng sửa kế hoạch đến khi hoàn tất lượt mới.</p><p>{{demoPlanState(p,data.sessions).stale?'Nguồn đã đổi — mở nguồn để review và tạo mục mới.':'Nguồn hiện hành.'}}</p><p v-if="p.status==='DONE'">{{demoPlanState(p,data.sessions).doneCurrent?'Đã tự ghi nhận luyện; nguồn và retry còn hiện hành.':'Đã tự ghi nhận trước đây; nguồn hoặc retry không còn hiện hành.'}}</p><div class="actions"><button :disabled="busy" @click="emit('open',p.sessionId)">Mở nguồn kế hoạch</button><button v-if="p.retryId" :disabled="busy" @click="emit('open',p.retryId!)">Tiếp tục retry kế hoạch</button><template v-if="p.status==='OPEN'"><button :disabled="busy||!!p.retryId||demoPlanState(p,data.sessions).stale" @click="run(()=>retryDemoPlan(toRaw(data),p.id,'GUIDED',Date.now()))">Retry kế hoạch có hướng dẫn</button><button :disabled="busy||!!p.retryId||demoPlanState(p,data.sessions).stale" @click="run(()=>retryDemoPlan(toRaw(data),p.id,'INDEPENDENT',Date.now()))">Retry kế hoạch độc lập</button><button :disabled="busy||!demoPlanState(p,data.sessions).canFinish" @click="run(()=>finishDemoPlan(toRaw(data),p.id,Date.now()))">Tự ghi nhận đã luyện</button></template><button :disabled="busy" @click="remove(p.id)">Xóa kế hoạch</button></div><form v-if="p.status==='OPEN'" @submit.prevent="run(()=>scheduleDemoPlan(toRaw(data),p.id,dates[p.id]??p.day))"><label>Đổi ngày luyện<input :value="dates[p.id]??p.day" @input="dates[p.id]=($event.target as HTMLInputElement).value" type="date" min="2000-01-01" max="2100-12-31" :disabled="busy"></label><button :disabled="busy">Lưu ngày luyện</button></form></article></section></template>
<style scoped>blockquote{white-space:pre-wrap;overflow-wrap:anywhere}</style>
